{
  "title": "agent.completions.message.InputAudio",
  "description": "Audio input for multimodal messages.",
  "type": "object",
  "properties": {
    "data": {
      "description": "Base64-encoded audio data.",
      "type": "string"
    },
    "format": {
      "description": "The audio format (e.g., \"wav\", \"mp3\").",
      "type": "string"
    }
  }
}

{
  "title": "functions.expression.Special",
  "description": "Predefined expression behaviors that require no user-authored code.",
  "anyOf": [
    {
      "title": "Input",
      "description": "Returns the params input as-is.",
      "type": "string",
      "enum": [
        "input"
      ]
    },
    {
      "title": "Output",
      "description": "Returns the params output as-is.",
      "type": "string",
      "enum": [
        "output"
      ]
    },
    {
      "title": "TaskOutputL1Normalized",
      "description": "L1-normalizes the output. Scalar/Err pass through.\nVector: L1 normalize. Vectors: L1 normalize each.",
      "type": "string",
      "enum": [
        "task_output_l1_normalized"
      ]
    },
    {
      "title": "TaskOutputWeightedSum",
      "description": "Weighted sum of the output. Vector → Scalar. Vectors → Vector.",
      "type": "string",
      "enum": [
        "task_output_weighted_sum"
      ]
    },
    {
      "title": "InputItemsOutputLength",
      "description": "Returns the length of input['items'] as u64",
      "type": "string",
      "enum": [
        "input_items_output_length"
      ]
    },
    {
      "title": "InputItemsOptionalContextSplit",
      "description": "Splits an input containing items and optionally context into multiple inputs",
      "type": "string",
      "enum": [
        "input_items_optional_context_split"
      ]
    },
    {
      "title": "InputItemsOptionalContextMerge",
      "description": "Merges multiple inputs containing items and optionally context into a single input",
      "type": "string",
      "enum": [
        "input_items_optional_context_merge"
      ]
    }
  ]
}

{
  "title": "agent.completions.message.ImageUrl",
  "description": "An image URL for multimodal input.",
  "type": "object",
  "properties": {
    "detail": {
      "description": "The detail level for image processing.",
      "anyOf": [
        {
          "$ref": "agent.completions.message.ImageUrlDetail"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "url": {
      "description": "The URL of the image (can be a data URL or HTTP URL).",
      "type": "string"
    }
  }
}

{
  "title": "agent.completions.message.RichContentPart",
  "description": "A part of rich content.",
  "anyOf": [
    {
      "title": "Text",
      "description": "Text content.",
      "type": "object",
      "properties": {
        "text": {
          "type": "string"
        },
        "type": {
          "type": "string",
          "enum": [
            "text"
          ]
        }
      }
    },
    {
      "title": "ImageUrl",
      "description": "An image URL.",
      "type": "object",
      "properties": {
        "image_url": {
          "$ref": "agent.completions.message.ImageUrl"
        },
        "type": {
          "type": "string",
          "enum": [
            "image_url"
          ]
        }
      }
    },
    {
      "title": "InputAudio",
      "description": "Audio input.",
      "type": "object",
      "properties": {
        "input_audio": {
          "$ref": "agent.completions.message.InputAudio"
        },
        "type": {
          "type": "string",
          "enum": [
            "input_audio"
          ]
        }
      }
    },
    {
      "title": "InputVideo",
      "description": "Video input.",
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "enum": [
            "input_video"
          ]
        },
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        }
      }
    },
    {
      "title": "VideoUrl",
      "description": "A video URL.",
      "type": "object",
      "properties": {
        "type": {
          "type": "string",
          "enum": [
            "video_url"
          ]
        },
        "video_url": {
          "$ref": "agent.completions.message.VideoUrl"
        }
      }
    },
    {
      "title": "File",
      "description": "A file.",
      "type": "object",
      "properties": {
        "file": {
          "$ref": "agent.completions.message.File"
        },
        "type": {
          "type": "string",
          "enum": [
            "file"
          ]
        }
      }
    }
  ]
}

{
  "title": "agent.completions.message.RichContentExpression",
  "description": "Expression variant of [`RichContent`] for dynamic content.",
  "anyOf": [
    {
      "title": "Text",
      "description": "Plain text content.",
      "type": "string"
    },
    {
      "title": "Parts",
      "description": "Multi-part content expressions.",
      "type": "array",
      "items": {
        "description": "A value that can be either a literal or an expression.\n\nThis allows Function definitions to mix static values with dynamic\nexpressions. During compilation, expressions are evaluated while\nliteral values pass through unchanged.\n\n# Example\n\nLiteral value:\n```json\n\"hello world\"\n```\n\nJMESPath expression:\n```json\n{\"$jmespath\": \"input.greeting\"}\n```\n\nStarlark expression:\n```json\n{\"$starlark\": \"input['greeting']\"}\n```",
        "anyOf": [
          {
            "title": "Expression",
            "description": "An expression (JMESPath or Starlark) to evaluate.",
            "$ref": "functions.expression.Expression"
          },
          {
            "title": "Value",
            "description": "A literal value.",
            "$ref": "agent.completions.message.RichContentPartExpression"
          }
        ]
      }
    }
  ]
}

{
  "title": "agent.completions.message.InputAudio",
  "description": "Audio input for multimodal messages.",
  "type": "object",
  "properties": {
    "data": {
      "description": "Base64-encoded audio data.",
      "type": "string"
    },
    "format": {
      "description": "The audio format (e.g., \"wav\", \"mp3\").",
      "type": "string"
    }
  }
}

{
  "title": "agent.completions.message.RichContent",
  "description": "Rich content for user/assistant messages (supports multimodal input).",
  "anyOf": [
    {
      "title": "Text",
      "description": "Plain text content.",
      "type": "string"
    },
    {
      "title": "Parts",
      "description": "Multi-part content (text, images, audio, video, files).",
      "type": "array",
      "items": {
        "$ref": "agent.completions.message.RichContentPart"
      }
    }
  ]
}
